#!/usr/bin/env bash
# Run from a workspace containing zenmath; records are generated by the MPFR tools.
set -euo pipefail
records=${1:?usage: check-core-math.sh RECORD_DIRECTORY}
features=()
if [[ -n ${ZENMATH_FEATURES:-} ]]; then features=(--features "$ZENMATH_FEATURES"); fi
runner=()
if [[ -n ${ZENMATH_RUNNER:-} ]]; then read -r -a runner <<< "$ZENMATH_RUNNER"; fi
bindir="${CARGO_TARGET_DIR:-target}${CARGO_BUILD_TARGET:+/$CARGO_BUILD_TARGET}/release/examples"
suffix=""
if [[ ${CARGO_BUILD_TARGET:-} == wasm32-* ]]; then suffix=.wasm; fi
cargo test -p zenmath "${features[@]}"
cargo clippy -p zenmath --all-targets --all-features -- -D warnings
cargo build -p zenmath --examples --release "${features[@]}"
for f in exp2f expf log2f logf log10f cbrtf powf sinf cosf tanf atanf atan2f tanhf log1pf expm1f acosf hypotf; do
    "${runner[@]}" "$bindir/core_math_check$suffix" "$f" "$records/$f.bin"
done
for f in cbrt exp2 exp log2 log log10 atan log1p sin cos atan2 tan pow atanh tanh asinh; do
    "${runner[@]}" "$bindir/core_math_check64$suffix" "$f" "$records/$f.bin"
done
